import{_ as a,o as l,c as i,ae as r}from"./chunks/framework.RRduUuAx.js";const g=JSON.parse('{"title":"Alipay 내역 가져오기","description":"","frontmatter":{},"headers":[],"relativePath":"v1/ko/guide/03-alipay-bill-import-guide.md","filePath":"v1/ko/guide/03-alipay-bill-import-guide.md"}'),o={name:"v1/ko/guide/03-alipay-bill-import-guide.md"};function e(d,t,n,s,h,c){return l(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="alipay-내역-가져오기" tabindex="-1">Alipay 내역 가져오기 <a class="header-anchor" href="#alipay-내역-가져오기" aria-label="Permalink to &quot;Alipay 내역 가져오기&quot;">​</a></h1><h2 id="📋-개요" tabindex="-1">📋 개요 <a class="header-anchor" href="#📋-개요" aria-label="Permalink to &quot;📋 개요&quot;">​</a></h2><p>이 가이드는 Alipay에서 거래 내역을 내보낸 다음, 코알라 가계부로 가져오는 방법을 안내합니다.</p><hr><h2 id="📱-1단계-alipay에서-내역-내보내기" tabindex="-1">📱 1단계: Alipay에서 내역 내보내기 <a class="header-anchor" href="#📱-1단계-alipay에서-내역-내보내기" aria-label="Permalink to &quot;📱 1단계: Alipay에서 내역 내보내기&quot;">​</a></h2><h3 id="단계-1-내역-账单-화면-열기" tabindex="-1">단계 1: 내역(账单) 화면 열기 <a class="header-anchor" href="#단계-1-내역-账单-화면-열기" aria-label="Permalink to &quot;단계 1: 내역(账单) 화면 열기&quot;">​</a></h3><ol><li>Alipay 앱을 엽니다</li><li>하단의 <strong>我的</strong>를 탭합니다</li><li><strong>账单</strong>을 탭해 내역 화면으로 이동합니다</li></ol><blockquote><p>📝 참고: Alipay 버전에 따라 메뉴 위치가 다를 수 있습니다. 찾기 어렵다면 Alipay 검색창에서 “账单”을 검색해 보세요.</p></blockquote><h3 id="단계-2-내보내기-시작" tabindex="-1">단계 2: 내보내기 시작 <a class="header-anchor" href="#단계-2-내보내기-시작" aria-label="Permalink to &quot;단계 2: 내보내기 시작&quot;">​</a></h3><ol><li>내역 화면 오른쪽 위 **...**를 탭합니다</li><li><strong>开具交易流水证明</strong> 또는 <strong>账单导出</strong>(표기 다를 수 있음)를 선택합니다</li><li><strong>用户个人对帐</strong>를 선택하고 <strong>申请</strong>를 탭합니다</li></ol><h3 id="단계-3-범위-수신-방법-선택" tabindex="-1">단계 3: 범위/수신 방법 선택 <a class="header-anchor" href="#단계-3-범위-수신-방법-선택" aria-label="Permalink to &quot;단계 3: 범위/수신 방법 선택&quot;">​</a></h3><ol><li>거래 유형: <strong>全部交易</strong> / <strong>收入</strong> / <strong>支出</strong></li><li>기간(예: 최근 1개월/최근 3개월)</li><li>수신 방법: <strong>支付宝</strong> / <strong>邮箱</strong></li></ol><blockquote><p>💡 팁:</p><ul><li>한 번에 3개월 이내로 내보내는 것을 권장합니다(파일이 커지면 처리 속도가 느려질 수 있습니다).</li><li>이메일로 받는 경우, Alipay에서 이메일 주소를 설정해야 할 수 있습니다.</li></ul></blockquote><h3 id="단계-4-기기에-파일-저장" tabindex="-1">단계 4: 기기에 파일 저장 <a class="header-anchor" href="#단계-4-기기에-파일-저장" aria-label="Permalink to &quot;단계 4: 기기에 파일 저장&quot;">​</a></h3><ol><li>이메일로 받은 경우: <ul><li>이메일 앱에서 Alipay 메일을 찾습니다</li><li>첨부파일(CSV)을 다운로드합니다</li><li>파일 관리자에서 접근 가능한 위치에 저장합니다</li></ul></li><li>“파일에 저장”이 가능한 경우: <ul><li>다운로드 폴더 등에 저장합니다</li><li>저장 위치를 기억해 둡니다</li></ul></li></ol><hr><h2 id="📱-2단계-코알라-가계부로-가져오기" tabindex="-1">📱 2단계: 코알라 가계부로 가져오기 <a class="header-anchor" href="#📱-2단계-코알라-가계부로-가져오기" aria-label="Permalink to &quot;📱 2단계: 코알라 가계부로 가져오기&quot;">​</a></h2><h3 id="단계-1-가져오기-화면-열기" tabindex="-1">단계 1: 가져오기 화면 열기 <a class="header-anchor" href="#단계-1-가져오기-화면-열기" aria-label="Permalink to &quot;단계 1: 가져오기 화면 열기&quot;">​</a></h3><ol><li>코알라 가계부 앱을 엽니다</li><li>하단의 <strong>설정</strong>을 탭합니다</li><li><strong>내역 가져오기</strong>를 찾아 들어갑니다</li></ol><h3 id="단계-2-가져오기-소스-선택" tabindex="-1">단계 2: 가져오기 소스 선택 <a class="header-anchor" href="#단계-2-가져오기-소스-선택" aria-label="Permalink to &quot;단계 2: 가져오기 소스 선택&quot;">​</a></h3><ol><li><strong>가져오기 소스</strong>를 탭합니다</li><li><strong>Alipay</strong>를 선택합니다</li></ol><blockquote><p>⚠️ 중요: 반드시 Alipay를 선택해야 합니다. 소스를 잘못 선택하면 파일을 제대로 파싱할 수 없습니다.</p></blockquote><h3 id="단계-3-파일-선택" tabindex="-1">단계 3: 파일 선택 <a class="header-anchor" href="#단계-3-파일-선택" aria-label="Permalink to &quot;단계 3: 파일 선택&quot;">​</a></h3><ol><li><strong>파일 경로</strong>를 탭합니다</li><li>Alipay에서 내보낸 CSV(<code>.csv</code>)를 선택합니다</li><li>파일명이 표시되는지 확인합니다</li></ol><h3 id="단계-4-장부-연결" tabindex="-1">단계 4: 장부 연결 <a class="header-anchor" href="#단계-4-장부-연결" aria-label="Permalink to &quot;단계 4: 장부 연결&quot;">​</a></h3><ol><li><strong>장부 연결</strong>을 탭합니다</li><li>가져올 장부를 선택합니다</li></ol><h3 id="단계-5-파싱-→-미리보기-→-가져오기" tabindex="-1">단계 5: 파싱 → 미리보기 → 가져오기 <a class="header-anchor" href="#단계-5-파싱-→-미리보기-→-가져오기" aria-label="Permalink to &quot;단계 5: 파싱 → 미리보기 → 가져오기&quot;">​</a></h3><ol><li>우측 상단의 <strong>파싱</strong>을 탭합니다</li><li>미리보기 화면에서 내역을 확인하고 필요 시 카테고리/계정/메모 등을 수정합니다</li><li><strong>가져오기</strong>를 탭합니다</li></ol><hr><h2 id="📋-alipay-csv-열-참고" tabindex="-1">📋 Alipay CSV 열(참고) <a class="header-anchor" href="#📋-alipay-csv-열-참고" aria-label="Permalink to &quot;📋 Alipay CSV 열(참고)&quot;">​</a></h2><p>Alipay CSV에는 보통 아래와 같은 열이 포함됩니다.</p><table tabindex="0"><thead><tr><th>열 이름(내보내기 표기)</th><th>의미</th><th>예시</th></tr></thead><tbody><tr><td>交易时间</td><td>거래 시간</td><td>2024-01-01 12:00:00</td></tr><tr><td>交易分类</td><td>분류</td><td>餐饮美食/日用百货</td></tr><tr><td>交易对方</td><td>상대방</td><td>张三 / 商户名称</td></tr><tr><td>对方账号</td><td>상대 계정</td><td><a href="mailto:xxx@163.com" target="_blank" rel="noreferrer">xxx@163.com</a></td></tr><tr><td>商品说明</td><td>내용</td><td>午餐 / 购物等</td></tr><tr><td>收/支</td><td>수입/지출</td><td>收入 / 支出</td></tr><tr><td>金额</td><td>금액</td><td>100.00</td></tr><tr><td>收/付款方式</td><td>결제 수단/계정</td><td>余额宝</td></tr><tr><td>交易状态</td><td>상태</td><td>交易成功 / 已退款</td></tr><tr><td>交易订单号</td><td>거래 주문 번호</td><td>20240101...</td></tr><tr><td>商家订单号</td><td>가맹점 주문 번호</td><td>1234567890</td></tr><tr><td>备注</td><td>메모</td><td>备注内容</td></tr></tbody></table><hr><h2 id="⚠️-유의사항" tabindex="-1">⚠️ 유의사항 <a class="header-anchor" href="#⚠️-유의사항" aria-label="Permalink to &quot;⚠️ 유의사항&quot;">​</a></h2><ol><li><strong>CSV만 지원</strong>: Alipay는 현재 CSV 내보내기만 지원합니다.</li><li><strong>중복/환불</strong>: 중복으로 판단되는 항목은 건너뛰어질 수 있으며, 환불 항목은 미리보기에서 확인해 주세요.</li><li><strong>파일을 임의로 수정하지 마세요</strong>: 헤더 변경, 열 삭제/추가 등은 파싱 실패의 흔한 원인입니다.</li></ol><hr><p><strong>마지막 업데이트</strong>: 2026년 5월</p>',37)])])}const u=a(o,[["render",e]]);export{g as __pageData,u as default};
